export const linePalette=[['Yellow','#e2b500'],['Red','#e84b40'],['Blue','#365da7'],['Green','#39976c'],['Purple','#8b5db3'],['Orange','#ed8836'],['Pink','#d05d9c'],['Teal','#168e98']];
export const lineColour=slot=>linePalette[slot]?.[1]??`hsl(${(slot*137.5)%360} 60% 42%)`;
export const lineName=slot=>(linePalette[slot]?.[0]??'Colour '+(slot+1))+' line';
export function freeLineSlot(state){let slot=0;while(state.links.some(l=>l.slot===slot))slot++;return slot;}
export function ensureLineSlots(state){const used=new Set();for(const l of state.links){if(!Number.isInteger(l.slot)||l.slot<0||used.has(l.slot)){let slot=0;while(used.has(slot))slot++;l.slot=slot;}used.add(l.slot);}state.lineSlot??=0;}
export function installLineDock({map,tools,state,node,refresh,inspect,vehicleLabels,onSelect=()=>{}}){
 const dock=node('div',null,'coastal-line-dock'),circles=node('div',null,'coastal-line-circles'),caption=node('span',null,'coastal-line-caption');circles.setAttribute('role','group');circles.setAttribute('aria-label','Choose a coloured line');dock.append(circles,caption);map.append(dock);tools.classList.add('coastal-line-transport');let key='';
 function update(){ensureLineSlots(state);const active=state.links.find(l=>l.slot===state.lineSlot);if(active)state.tool=active.type;const next=JSON.stringify([state.lineSlot,state.tool,state.links.map(l=>[l.slot,l.type,l.nodes]),state.round]);if(next===key)return;key=next;circles.replaceChildren();const count=Math.max(7,freeLineSlot(state)+1,...state.links.map(l=>l.slot+2));for(let slot=0;slot<count;slot++){const link=state.links.find(l=>l.slot===slot),b=node('button');b.type='button';b.className='coastal-line-dot';b.dataset.lineSlot=slot;b.style.setProperty('--line-colour',lineColour(slot));b.dataset.built=String(Boolean(link));b.setAttribute('aria-pressed',String(state.lineSlot===slot));b.setAttribute('aria-label',link?lineName(slot)+' · '+vehicleLabels[link.type]:'New '+lineName(slot));b.title=link?lineName(slot)+' · '+vehicleLabels[link.type]+'. Select, then tap again for stats and upgrades.':'New '+lineName(slot)+'. Choose transport, then drag between stops; pay the displayed route price.';b.textContent=link?String(slot+1):'+';b.onclick=()=>{if(link&&state.lineSlot===slot){inspect(state.links.indexOf(link));return;}onSelect();state.lineSlot=slot;state.selected=null;if(link)state.tool=link.type;refresh();};circles.append(b);}const selected=state.links.find(l=>l.slot===state.lineSlot);tools.hidden=Boolean(selected);caption.textContent=selected?lineName(state.lineSlot)+' · '+vehicleLabels[selected.type]+(selected.nodes?.length>=4&&selected.nodes[0]===selected.nodes.at(-1)?' · Loop service':selected.type!=='tunnel'?' · Extend or join ends to loop':' · Select grey for a new line')+' · Tap colour for details':'New '+lineName(state.lineSlot)+' · Choose transport, then drag';}
 return {refresh:update};
}
